{"code":"def transform(grid):
    h,w=len(grid),len(grid[0])
    # separator lines of 1s
    vr=[j for j in range(w) if sum(grid[i][j]==1 for i in range(h))>=h-1]
    hr=[i for i in range(h) if sum(grid[i][j]==1 for j in range(w))>=w-1]
    c=vr[0]; r=hr[0]
    boxes=[]
    for r0,r1,c0,c1 in [(0,r,0,c),(0,r,c+1,w),(r+1,h,0,c),(r+1,h,c+1,w)]:
        pts=[(i,j) for i in range(r0,r1) for j in range(c0,c1) if grid[i][j] not in (0,1)]
        if pts:
            a,b=min(i for i,j in pts),max(i for i,j in pts); x,y=min(j for i,j in pts),max(j for i,j in pts)
            boxes.append((a,b,x,y))
        else: boxes.append((r0,r0,c0,c0))
    H=max(b-a+1 for a,b,x,y in boxes); W=max(y-x+1 for a,b,x,y in boxes)
    out=[[0]*(2*W) for _ in range(2*H)]
    for k,(a,b,x,y) in enumerate(boxes):
        rr=(k//2)*H; cc=(k%2)*W
        for i in range(a,b+1):
            for j in range(x,y+1): out[rr+i-a][cc+j-x]=grid[i][j]
    return out"}

